import {useState} from 'react';
import {Field,Form,Status} from './ui';
import {Blank,Feedback,Section} from './common';
import {platform,useResource,timestamp} from './data';
import {api} from './api';
export default function Admin(){
 const r=useResource(()=>platform('/admin/reviews')),[selection,setSelection]=useState(null),[notice,setNotice]=useState('');
 const entries=r.data?[...r.data.organizations.map(o=>({...o,type:'organization',key:o.id,title:o.name})),...r.data.riders.map(o=>({...o,type:'rider',key:o.user_id,title:`${o.vehicle} rider`}))]:[];
 return <><h1>Trust starts with careful review.</h1><p className="muted">Authorized organization and rider verification. Sensitive actions require fresh MFA authentication.</p><Feedback resource={r}/>{r.error?<p className="notice">If you have an authorized administrator role, open Security and verify your identity before refreshing this queue.</p>:null}{r.data?<Section title="Verification queue" action={<button className="secondary" onClick={r.refresh}>Refresh</button>}><div className="review-layout"><div className="review-list">{entries.length?entries.map(item=><button key={item.key} className={`review-item ${selection?.key===item.key?'selected':''}`} onClick={()=>{setSelection(item);setNotice('');}}><strong>{item.title}</strong><small>{item.type} · {item.country??item.vehicle}</small><Status value={item.status}/></button>):<Blank title="No applications yet."/>}</div>{selection?<div className="form-panel" key={selection.key}><h2>{selection.title}</h2><p className="small order-id">{selection.key}</p><p>Submitted {timestamp(selection.created_at)}</p><Status value={selection.status}/>{selection.type==='rider'?<div className="rider-review-evidence"><p><strong>Vehicle:</strong> {selection.vehicle}</p><p><strong>Plate number:</strong> {selection.vehicle_plate||'Not required'}</p>{selection.plate_photo?<a href={selection.plate_photo} target="_blank" rel="noreferrer"><img className="rider-plate-proof" src={selection.plate_photo} alt="Submitted vehicle plate evidence"/></a>:<p className="small muted">No plate photo submitted.</p>}</div>:null}<Form submit="Record review" onSubmit={async d=>{await platform('/admin/reviews','POST',{...d,type:selection.type,id:selection.key});setSelection(null);setNotice('Review recorded and applicant notified.');await r.refresh();}}><Field label="Decision"><select name="status"><option value="approved">Approve</option><option value="rejected">Reject</option><option value="suspended">Suspend</option></select></Field><Field label="Review reason"><textarea name="reason" minLength={10} maxLength={1000} required/></Field><p className="small muted">Only approve after completing actual verification. Local test data must be identified as such in the reason.</p></Form></div>:<Blank title="Choose an application.">Review organization and rider applications within your assigned authority.</Blank>}</div></Section>:null}{notice?<p role="status" className="notice">{notice}</p>:null}</>;
}
export function TradeControl({user}){
 const r=useResource(()=>api('/trade')),[notice,setNotice]=useState('');
 return <><h1>International Trade controls.</h1><p className="muted">Primary Super Admin authority is enforced by the server. MFA is required. Unlocking never configures providers or grants country operating permission.</p><Feedback resource={r}/>{r.data?<div className="form-panel"><p>Current state: <strong>{r.data.enabled?'Unlocked':'Locked'}</strong></p><pre className="safe-json">{JSON.stringify(r.data,null,2)}</pre><Form submit="Submit trade state change" onSubmit={async d=>{await api('/admin/trade','POST',{enabled:d.enabled==='true',revision:Number(d.revision),countries:d.countries.split(',').map(c=>c.trim().toUpperCase()).filter(Boolean),reason:d.reason});setNotice('Trade state updated.');await r.refresh();}}><Field label="Requested state"><select name="enabled"><option value="false">Locked</option><option value="true">Unlocked</option></select></Field><Field label="Expected revision" name="revision" type="number" min="0" required defaultValue={r.data.revision??0}/><Field label="Country codes, separated by commas" name="countries" placeholder="No countries enabled" defaultValue={r.data.countries.map(c=>c.code??c).join(', ')}/><Field label="Reason"><textarea name="reason" minLength={10} required maxLength={1000}/></Field></Form></div>:null}{notice?<p role="status" className="notice">{notice}</p>:null}</>;
}
export function AdminAccounts(){
 const r=useResource(()=>platform('/admin/accounts')),[notice,setNotice]=useState('');
 return <><h1>Manage platform authority.</h1><p className="muted">Primary can manage all levels. Lesser Super Admins can manage ordinary administrators only. All changes require fresh MFA and revoke the target's sessions.</p><Feedback resource={r}/>{r.data?<Section title="Administrator accounts"><div className="table-wrap"><table><thead><tr><th>User ID</th><th>Level</th><th>Permissions</th></tr></thead><tbody>{r.data.accounts.map(a=><tr key={a.user_id}><td className="order-id">{a.user_id}</td><td>{a.level.replaceAll('_',' ')}</td><td>{(typeof a.permissions==='string'?JSON.parse(a.permissions):a.permissions).join(', ')||'None'}</td></tr>)}</tbody></table></div></Section>:null}<div className="form-panel"><h2>Assign administrator authority</h2><Form submit="Save administrator" onSubmit={async d=>{await platform('/admin/accounts','POST',{userId:d.userId,level:d.level,permissions:d.permissions.split(',').map(p=>p.trim()).filter(Boolean)});setNotice('Administrator authority updated.');await r.refresh();}}><Field label="Registered user ID" name="userId" required maxLength={100}/><Field label="Administrator level"><select name="level"><option value="ordinary">Ordinary administrator</option><option value="lesser_super_admin">Lesser Super Admin</option></select></Field><Field label="Permissions, separated by commas" name="permissions" placeholder="organization_verification_admin, rider_verification_admin" maxLength={1000}/><p className="small muted">International roles stay locked until Primary activation. Permission names must match the platform contracts.</p></Form></div>{notice?<p role="status" className="notice">{notice}</p>:null}</>;
}
